/**
 * Bridge for CreatureModal — content rendered in Svelte ({@html}), not creatureModalContent.innerHTML.
 */

import { awaitLazyModalReady } from '../lib/lazyModalMounts.ts';

type ShowFn = (html: string) => void;
type CloseFn = () => void;

let _show: ShowFn | null = null;
let _close: CloseFn | null = null;
let _pendingHtml: string | null = null;
let _pendingPaintedWait: (() => void) | null = null;

export function setCreatureModalShow(fn: ShowFn | null): void {
  _show = typeof fn === 'function' ? fn : null;
  if (_show && _pendingHtml !== null) {
    const html = _pendingHtml;
    _pendingHtml = null;
    try {
      _show(html);
    } catch {
      // Graceful error handling
    }
    if (_pendingPaintedWait) {
      const resolve = _pendingPaintedWait;
      _pendingPaintedWait = null;
      void whenCreatureModalPainted().then(resolve);
    }
  }
}

export function setCreatureModalClose(fn: CloseFn | null): void {
  _close = typeof fn === 'function' ? fn : null;
}

export async function showCreatureModalContent(html: string): Promise<void> {
  await awaitLazyModalReady('creatureModal');
  if (_show) {
    try {
      _show(html);
    } catch {
      // Graceful error handling
    }
  } else {
    _pendingHtml = html;
  }
}

/** After Svelte {@html} has painted (two animation frames). */
export function whenCreatureModalPainted(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
    } else {
      resolve();
    }
  });
}

export async function showCreatureModalContentWhenPainted(html: string): Promise<void> {
  await awaitLazyModalReady('creatureModal');
  if (_show) {
    try {
      _show(html);
    } catch {
      // Graceful error handling
    }
    await Promise.resolve();
    await whenCreatureModalPainted();
    return;
  }
  _pendingHtml = html;
  await new Promise<void>((resolve) => {
    _pendingPaintedWait = resolve;
  });
}

export function closeCreatureModalBridge(): void {
  try {
    _close?.();
  } catch {
    // Graceful error handling
  }
}

export function resetCreatureModalBridgeForTests(): void {
  _show = null;
  _close = null;
  _pendingHtml = null;
  _pendingPaintedWait = null;
}

if (typeof globalThis !== 'undefined') {
  (globalThis as Record<string, unknown>).__showCreatureModalContent = showCreatureModalContent;
  (globalThis as Record<string, unknown>).__closeCreatureModalBridge = closeCreatureModalBridge;
}
